from __future__ import annotations
from pathlib import Path
from .pipeline.callbacks import PipelineState
from marisco.handlers.pipeline.assembly import (
    run_finalize as _run_finalize,
    run_preflight as _run_preflight,
)
from .pipeline.contracts import HandlerConfig, PluginSpec
from .pipeline.gates import gap_check
from .pipeline.intake import call_loader, resolve_loader_fn
from .pipeline.writer  import write_netcdf


